sys_ui_context_menu.action_script:
var nsProTaskMain;

nsProTaskMain = parent.top.window.gsft_main;

moveProposedToCurrent();

function moveProposedToCurrent(){

	var selected;
	selected = g_list.getChecked();
	if(selected.length == 0)
	{
		selected = g_sysId;
	}
	var port = new GlideAjax('x_g_sonc_ns_pro.port_ajax');
	port.addParam('sysparm_name', 'moveSelectedPortsToCurrent');
	port.addParam('sysparm_selectedPorts', selected);
	port.getXMLAnswer(getResponse);

    function getResponse(response) {
		//alert(response);
        var responseObj = JSON.parse(response);
        if (responseObj.resultCode == 'success') {
			nsProTaskMain.g_form.addInfoMessage(response.message);
        } else {
            nsProTaskMain.g_form.addErrorMessage(response.message);
        }
        gsftSubmit(null, nsProTaskMain.g_form.getFormElement(), 'sysverb_update_and_stay');
    }

}

sys_ui_context_menu.on_show_script:
canBeConfigured();

function canBeConfigured() {

    var proposed = false;

            if (g_list.getView() == 'proposedports' || g_list.getView() == 'nspro') {
                proposed = true;
            }

    if (proposed) {
        g_menu.setEnabled(g_item);
        g_menu.setLabel(g_item, "<b style='color:DodgerBlue;'>• Move Proposed to Current •</b>");

    } else {
        g_menu.setDisabled(g_item);
    }

}
